import{_ as a,a0 as o,w as s,s as l,ao as c,I as n,x as r,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux script命令 —— 終端裏的記錄器 | LCTT x X-CMD","titleTemplate":false,"description":"Linux script命令 —— 終端裏的記錄器 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux script命令 —— 終端裏的記錄器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux script命令 —— 終端裏的記錄器 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140530 Linux script command--A recorder inside your Terminal","title":"Linux script命令 —— 終端裏的記錄器","tag":"201406","desc":""},"relativePath":"201406/20140530 Linux script command--A recorder inside your Terminal.md","filePath":"[post].md"}'),d={name:"201406/20140530 Linux script command--A recorder inside your Terminal.md"};function m(h,t,u,g,x,f){const i=o("Link");return s(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux-script命令-——-終端裏的記錄器" tabindex="-1">Linux script命令 —— 終端裏的記錄器 <a class="header-anchor" href="#linux-script命令-——-終端裏的記錄器" aria-label="Permalink to “Linux script命令 —— 終端裏的記錄器”">​</a></h1><p>當你在終端或者控制台工作時，你可能想要記錄在終端中所做的一切。這些記錄可以用來當作史料，保存終端所發生的一切。比如説，你和一些Linux管理員們同時管理着相同的機器，或者你讓某人遠程登陸到了你的服務器上，你可能記錄想要終端裏發生的一切。要實現這個目標，你可以使用script命令。</p><h3 id="script是什麼" tabindex="-1">script是什麼 <a class="header-anchor" href="#script是什麼" aria-label="Permalink to “script是什麼”">​</a></h3><p>scirpt就是一個命令，可以製作一份記錄輸出到終端的記錄。對於那些想要真實記錄終端會話的人來説，這很有用。該記錄可以保存並在以後再打印出來。</p><h3 id="怎麼用" tabindex="-1">怎麼用 <a class="header-anchor" href="#怎麼用" aria-label="Permalink to “怎麼用”">​</a></h3><p>默認情況下，我們可以通過在終端中輸入script來啓動scirpt命令。</p><pre><code>pungki@dev-machine:~$ script
Script started, file is typescript
pungki@dev-machine:~$
</code></pre><p>你也可以指定目標文件名來記錄打印結果。</p><pre><code>pungki@dev-machine:~$ script myfile
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/start_script.png" alt="Define script file"></p><p>當你再次見到命令提示符，這意味着終端將記錄打印到終端的任何東西。</p><p>你會看到當前目錄，有個名為myscript的文件。（LCTT譯註，此處原文有誤。這裏指定了記錄文件名為myfile，而不是默認的 typescript。）</p><h3 id="為什麼我們要用script命令" tabindex="-1">為什麼我們要用script命令 <a class="header-anchor" href="#為什麼我們要用script命令" aria-label="Permalink to “為什麼我們要用script命令”">​</a></h3><p>因為在之前已經提到過，script命令的主要功能是記錄所有的東西。下面給出了兩個使用該命令的場景。</p><h4 id="和同事共事時" tabindex="-1">和同事共事時 <a class="header-anchor" href="#和同事共事時" aria-label="Permalink to “和同事共事時”">​</a></h4><p>當和同事一起工作時，我們可以通過script來記錄你的活動。</p><p>比如，我們會使用名為<strong>collaborate</strong>的打印文件，來完成打印：</p><pre><code>$ script collaborate
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/collaborate.png" alt="Create collaborate file"></p><p>然後，在完成一些任務後，假如你需要把你幹的活發給另外一個工程師，那就把那文件發給他。所以當另外一個工程師需要複查所做的事情，他只要用文本編輯器打開這個文件就行了。</p><p>如果他想要更新該文件（以增加他的工作部分），可以使用<strong>-a</strong>選項。</p><pre><code>$ script -a collaborate
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/collaborate_append.png" alt="Append the file"></p><h4 id="記錄某人在終端中的所作所為" tabindex="-1">記錄某人在終端中的所作所為 <a class="header-anchor" href="#記錄某人在終端中的所作所為" aria-label="Permalink to “記錄某人在終端中的所作所為”">​</a></h4><p>你可能讓你的工程師或者某個人遠程訪問你的系統，要確保你的工程師正在幹正確的事，你可以記錄下他在你係統上的所作所為。要讓script命令在登錄時自動運行，我們可以把它添加進shell環境配置文件中。如果你正在使用<strong>bash</strong> shell，把這一行加進你的bash環境配置文件中。</p><pre><code>$ vi ~/.profile

# run the script command to record everything
# use -q for quite and -a option to append the script
#
/usr/bin/script -qa /usr/local/script/log_record_script
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/script_login.png" alt="Add script to bash profile"></p><p>然後保存。下次他登錄進你的系統時，script命令就會自動運行，並把日誌記錄進<strong>/usr/local/script/log_record_script</strong>。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/remote_script_quite.png" alt="Script without notification"></p><p><strong>-q</strong>選項可以讓scirpt命令以靜默模式運行，登錄進來的用户不會知道script命令已經運行了。而<strong>-a</strong>選項將會讓記錄附加到文件中，而不會擦除先前的記錄。</p><p>如果不使用<strong>-q</strong>選項，那麼當用户登錄進來時，他會收到像下圖中這樣的通知。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/remote_script.png" alt="Script with notification"></p><h3 id="退出記錄" tabindex="-1">退出記錄 <a class="header-anchor" href="#退出記錄" aria-label="Permalink to “退出記錄”">​</a></h3><p>要退出記錄活動，我們可以在終端中按下<strong>Ctrl+D</strong>，或者輸入<strong>exit</strong>。在退出script前，你會發現記錄文件的大小為0 Kb，而在退出之後，文件大小會發生改變。</p><h3 id="結尾" tabindex="-1">結尾 <a class="header-anchor" href="#結尾" aria-label="Permalink to “結尾”">​</a></h3><p>Script命令在你需要記錄或者存檔終端活動時可能很有用，記錄文件會存儲為文本文件，所以可以很方便地用文本編輯器打開。跟平常一樣，我們都可以通過輸入<strong>man script</strong>或者<strong>scirpt -h</strong>來顯示幫助頁並查看更多詳細用法。</p><hr>`,37)),n("p",null,[t[1]||(t[1]=r("via: ",-1)),e(i,{href:"http://linoxide.com/linux-command/script-command-recorder/"},{default:p(()=>[...t[0]||(t[0]=[r("http://linoxide.com/linux-command/script-command-recorder/",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=r("譯者：",-1)),e(i,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[2]||(t[2]=[r("GOLinux",-1)])]),_:1}),t[5]||(t[5]=r(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=r("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[r("LCTT",-1)])]),_:1}),t[9]||(t[9]=r(" 原創翻譯，",-1)),e(i,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[r("Linux中國",-1)])]),_:1}),t[10]||(t[10]=r(" 榮譽推出",-1))])])}const _=a(d,[["render",m]]);export{L as __pageData,_ as default};
